": "iGih4QSBWfmpkdGY", "name": "Postgres account"}}}, {"parameters": {"jsCode": "let UserPrompt = '';\\nlet SystemPrompt = '';\\nlet PostProductPrompt = '';\\n\\n// User prompt\\nconst roller_summary = $('Получение rolling summary главы для промта').first().json?.roller_summary;\\nif (roller_summary && Object.keys(roller_summary)?.length) {\\n  UserPrompt += `\\n## КРАТКОЕ СОДЕРЖАНИЕ ПРЕДЫДУЩЕЙ ГЛАВЫ:\\n${JSON.stringify(roller_summary)}\\n`;\\n}\\n\\nconst roller_summary_arc = $('Чтение текущей арки').first().json.summary;\\nif (roller_summary_arc && Object.keys(roller_summary_arc)?.length) {\\n  UserPrompt += `\\n## КРАТКОЕ ОПИСАНИЕ ТЕКУЩЕЙ АРКИ:\\n${JSON.stringify(roller_summary_arc)}\\n`;\\n}\\n\\nif ($('Выбор чанка для перевода').first().json?.prev_line) {\\n  UserPrompt += `\\n<CONTEXT_BEFORE>\\n${$('Выбор чанка для перевода').first().json.prev_line}\\n</CONTEXT_BEFORE>\\n`;\\n}\\n\\nUserPrompt += `\\n## ПЕРЕВЕДИ СТРОГО НА РУССКИЙ:\\n${$('Выбор чанка для перевода').first().json.chunk_text}\\n`;\\n\\n//System Prompt\\nSystemPrompt += $('Чтение промтов').all().find(item => item.json.name === 'BP Default')?.json?.prompt || '';\\n\\nlet glossary_text = '';\\nconst glossary = $('Чтение глоссария').all();\\nglossary_text = glossary.map((item) => \\n  Object.keys(item.json).length \\n  ? `${item.json.name} = ${item.json.translate}${item.json.gender ? ' (gender: ' + (item.json.gender.toLowerCase().includes('муж') ? 'male' : (item.json.gender.toLowerCase().includes('жен') ? 'female' : item.json.gender)) + ').'  : '.'}` : '').join('\\\\n');\\nif (glossary_text.length) {\\n  glossary_text = \\n`━━━━━━━━━━━━━━━━━━━━━━━━━━━\\nГЛОССАРИЙ — ИСТОЧНИК ИСТИНЫ\\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\\n${glossary_text}`;\\n}\\nSystemPrompt = SystemPrompt.replace('{{GLOSSARY}}', glossary_text)\\n\\nlet customPrompt = $('Чтение промтов').all().find(item => item.json.name === 'BP BL')?.json?.prompt || '';\\nif (customPrompt) {\\n  customPrompt =`\\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\\nROMAN_RULES — ПРИМЕНЯТЬ ВСЕГДА. БЕЗ ИСКЛЮЧЕНИЙ.\\nИМЕЮТ ПРИОРИТЕТ НАД ВСЕМИ ОСТАЛЬНЫМИ ПРАВИЛАМИ.\\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\\n${customPrompt}`;\\n}\\nSystemPrompt = SystemPrompt.replace('{{ROMAN_RULES}}', customPrompt)\\n\\nlet contestBefore_text = ''\\nif ($('Выбор чанка для перевода').first().json?.prev_line) {\\n  contestBefore_text += `\\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\\nСЕКЦИЯ<CONTEXT_BEFORE>\\n━━━━━━━━━━━━━━━━━━━━━━━━━━━\\nНЕ переводить.\\nИспользовать только для улучшения связности основного текста.\\n`\\n}\\nSystemPrompt = SystemPrompt.replace('{{CONTEXT_BEFORE}}', contestBefore_text)\\n\\nlet isRomanRules = 'Чётко отслеживается, кто говорит и кто действует?';\\nif (customPrompt) isRomanRules = 'ROMAN_RULES соблюдены?';\\nSystemPrompt = SystemPrompt.replace('{{IS_ROMAN_RULES}}', isRomanRules)\\n\\nreturn { UserPrompt, SystemPrompt, PostProductPrompt };\\n"}, "type": "n8n-nodes-base.code", "typeVersion": 2, "position": [-448, 384], "id": "5afbff5e-93f0-4be1-8a61-5bed4aa9f112", "name": "Формирование промтов для перевода"}, {"parameters": {"operation": "executeQuery", "query": "UPDATE  document_chunks SET status = 'processing', updated_at = now()\\n  WHERE id = {{ $('Выбор чанка для перевода').first().json.id }};\\n\\nUPDATE  document_chapters SET status = 'processing', updated_at = now()\\n  WHERE id = {{ $('Выбор чанка для перевода').item.json.chapter }};\\n  ", "options": {"queryReplacement": "='{{ $input.all() }}'"}}, "type": "n8n-nodes-base.postgres", "typeVersion": 2.6, "position": [-912, 384], "id": "b49cd2cc-8887-4638-8d60-5ba740f4c6cf", "name": "Перевод чанка в статус proccessing", "executeOnce": true, "alwaysOutputData": true, "retryOnFail": true, "credentials": {"postgres": {"id": "iGih4QSBWfmpkdGY", "name": "Postgres account"}}}, {"parameters": {"operation": "executeQuery", "query": "SELECT * FROM document_chapters WHERE job_id IN (SELECT job_id FROM job_current) AND id = {{ $('Выбор чанка для перевода').item.json.chapter }};", "options": {}}, "type": "n8n-nodes-b